-- Sample database: Banking
-- GENERATED by app/sample_dbs/generate.py — do not edit by hand

CREATE TABLE customers (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name   varchar(100) NOT NULL,
  national_id char(13) NOT NULL UNIQUE,
  birth_date  date NOT NULL,
  city        varchar(60),
  joined_at   date NOT NULL
);
CREATE TABLE accounts (
  id            integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id   integer NOT NULL REFERENCES customers(id),
  account_no    varchar(12) NOT NULL UNIQUE,
  account_type  varchar(20) NOT NULL CHECK (account_type IN ('savings','checking','fixed')),
  status        varchar(10) NOT NULL CHECK (status IN ('active','closed','frozen')),
  opened_at     date NOT NULL,
  balance       numeric(14,2) NOT NULL DEFAULT 0
);
CREATE TABLE transactions (
  id          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id  integer NOT NULL REFERENCES accounts(id),
  txn_type    varchar(20) NOT NULL CHECK (txn_type IN ('deposit','withdrawal','transfer_in','transfer_out','fee','interest')),
  amount      numeric(14,2) NOT NULL,
  txn_at      timestamp NOT NULL,
  description varchar(200)
);
CREATE TABLE loans (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id    integer NOT NULL REFERENCES customers(id),
  loan_type      varchar(20) NOT NULL CHECK (loan_type IN ('personal','home','car','business')),
  principal      numeric(14,2) NOT NULL,
  interest_rate  numeric(5,2) NOT NULL,
  term_months    integer NOT NULL,
  status         varchar(10) NOT NULL CHECK (status IN ('pending','approved','rejected','paid_off')),
  applied_at     date NOT NULL,
  approved_at    date
);
CREATE INDEX idx_accounts_customer ON accounts(customer_id);
CREATE INDEX idx_txn_account_time ON transactions(account_id, txn_at);
CREATE INDEX idx_loans_customer ON loans(customer_id);

COMMENT ON TABLE customers IS 'ลูกค้าธนาคาร — บางคนยังไม่มีบัญชี';
COMMENT ON TABLE accounts IS 'บัญชี — balance = ผลรวม amount ของ transactions ในบัญชีนั้น';
COMMENT ON TABLE transactions IS 'ธุรกรรม — amount เป็นบวก = เงินเข้า, ติดลบ = เงินออก';
COMMENT ON COLUMN transactions.amount IS 'บวก: deposit/transfer_in/interest, ลบ: withdrawal/transfer_out/fee';
COMMENT ON TABLE loans IS 'สินเชื่อ — approved_at เป็น NULL ถ้ายังไม่อนุมัติหรือถูกปฏิเสธ';















